CREATE TABLE IF NOT EXISTS governance_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, document_type text NOT NULL, version text NOT NULL DEFAULT '1.0', status text NOT NULL DEFAULT 'Draft', owner text, jurisdiction text NOT NULL DEFAULT 'Continental', review_cycle text NOT NULL DEFAULT 'Annual', next_review_date date, summary text, document_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());